-- =====================================================================
--  Prime Script — Contenu prêt à l'emploi (1/12) : Présentations (secteur × étape)
--
--  Ce fichier s'importe avec les autres fichiers de database/content/ :
--      php tools/import-content.php
--  (ou, en MySQL : mysql -u ... prime_script < database/content/content.sql
--   si ce fichier a été concaténé dans content.sql).
--
--  Format d'une ligne de contenu (JSON, une ligne par enregistrement) :
--    {"code": "...", "type": "...", "sector": "...", "stage": "...",
--     "service": "...", "title": "...", "position": 10, "content": "<p>…</p>"}
--
--    code     identifiant stable du bloc (réimport = mise à jour, jamais de doublon)
--    type     presentation | accroche | barrage | repondeur | decouverte |
--             argumentaire | preuve | tarif | appel_action | conclusion
--    sector   slug du secteur (architectes, artisans-btp, restauration, services-b2b)
--    stage    slug de l'étape (premier-appel, relance, closing)
--    service  slug du service (site-web, application, automatisation-ia, chatbot-ia)
--    content  HTML simple : <p>, <ul>, <li>, <strong>, <em>
--
--  Convention d'écriture : le texte à dire est en clair, l'aide au commercial
--  est sur une ligne « Conseil : … » en italique (<p><em>Conseil : …</em></p>).
-- =====================================================================

SET NAMES utf8mb4;

{"code": "pres-architectes-premier-appel", "type": "presentation", "sector": "architectes", "stage": "premier-appel", "title": "Agence d'architecture — premier contact", "content": "<p>Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions. Nous travaillons avec des agences d'architecture et des bureaux d'études sur leur site et leurs outils internes.</p><p>Ce qu'on entend souvent : beaucoup de bouche-à-oreille, mais peu de projets visibles en ligne.</p><ul><li>Un seul interlocuteur, du premier échange à la mise en ligne</li><li>Un site qui met vos réalisations en valeur avec de vraies photos</li><li>Des prix annoncés dès le départ, un devis écrit sans engagement</li></ul><br><em>Conseil : un nom d'architecte s'entend mal au téléphone. Épelez-le une fois, lentement.</em>"}
{"code": "pres-architectes-relance", "type": "presentation", "sector": "architectes", "stage": "relance", "title": "Agence d'architecture — relance", "content": "<p>Rebonjour {contact}, {prenom_commercial} de Prime Vision Solutions. Je vous avais parlé du site de votre agence.</p><ul><li>Je ne reprends pas tout depuis le début : je viens seulement voir où vous en êtes</li><li>Deux points restaient à trancher : le budget et la partie « projets » du site</li><li>Le devis que je vous ai envoyé est toujours valable, sans engagement</li></ul><br><em>Conseil : proposez un créneau précis en fin de phrase. « Mardi à 14 h » se refuse moins qu'« un jour ».</em>"}
{"code": "pres-architectes-closing", "type": "presentation", "sector": "architectes", "stage": "closing", "title": "Agence d'architecture — closing", "content": "<p>Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions. On touche au but sur votre site.</p><ul><li>Le devis est posé, le calendrier aussi</li><li>Il reste une question : c'est le démarrage ou le découpage en deux paiements ?</li><li>Une fois votre accord, on planifie le premier atelier de photos</li></ul><br><em>Conseil : ne dites jamais « oui » à la place du client. Posez la question et laissez le silence faire son travail.</em>"}
{"code": "pres-artisans-btp-premier-appel", "type": "presentation", "sector": "artisans-btp", "stage": "premier-appel", "title": "Artisan ou entreprise du bâtiment — premier contact", "content": "<p>Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions. Nous aidons des artisans et des entreprises de rénovation à répondre plus vite à leurs demandes.</p><p>La plupart de ceux qu'on rencontre reçoivent leurs demandes par téléphone, souvent sur le chantier.</p><ul><li>Un site qui montre vos chantiers, avant et après</li><li>Les demandes de devis qui arrivent au même endroit, sans être perdues</li><li>Des prix annoncés, un devis écrit, le code remis à vous</li></ul><br><em>Conseil : appelez en fin de journée ou à l'heure du déjeuner. Sur le chantier, personne ne décroche.</em>"}
{"code": "pres-artisans-btp-relance", "type": "presentation", "sector": "artisans-btp", "stage": "relance", "title": "Artisan ou BTP — relance", "content": "<p>Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions. Je reviens vers vous sur le site qu'on avait évoqué.</p><ul><li>Vous m'aviez dit que la période était chargée, je comprends très bien</li><li>Ce qui compte pour vous, c'était surtout de ne plus perdre de demandes</li><li>On peut commencer par la partie la plus simple : la page d'accueil et le formulaire</li></ul><br><em>Conseil : si la personne est sur un chantier, demandez tout de suite l'heure du rappel. N'insistez pas.</em>"}
{"code": "pres-artisans-btp-closing", "type": "presentation", "sector": "artisans-btp", "stage": "closing", "title": "Artisan ou BTP — closing", "content": "<p>Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions. J'ai le devis sous les yeux, on peut le finaliser ensemble.</p><ul><li>Le périmètre est écrit noir sur blanc, avec le prix exact</li><li>Vous pourrez mettre vos photos de chantier vous-même, sans nous appeler</li><li>Reste à choisir la date de départ : cette semaine ou après les congés ?</li></ul><br><em>Conseil : reformulez le besoin avec ses mots à lui, pas avec les vôtres. C'est ce qui déclenche la décision.</em>"}
{"code": "pres-restauration-premier-appel", "type": "presentation", "sector": "restauration", "stage": "premier-appel", "title": "Restaurant ou traiteur — premier contact", "content": "<p>Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions. Nous travaillons avec des restaurants et des traiteurs sur leur site et leurs réservations.</p><p>Ce qui revient tout le temps : des réservations qui se perdent, et des appels en plein service.</p><ul><li>Une page simple avec la carte, les horaires et la réservation en ligne</li><li>Un assistant qui répond aux questions d'horaires et d'accès, même le soir</li><li>Des prix de départ clairs, un devis écrit sans engagement</li></ul><br><em>Conseil : évitez d'appeler entre midi et 14 h, et après 19 h. Le service passe avant tout.</em>"}
{"code": "pres-restauration-relance", "type": "presentation", "sector": "restauration", "stage": "relance", "title": "Restaurant ou traiteur — relance", "content": "<p>Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions. Je vous avais parlé de la réservation en ligne.</p><ul><li>Je ne vous rappelle pas pour vous embêter : juste pour savoir si le sujet est toujours d'actualité</li><li>La réservation en ligne peut se brancher sur votre site actuel, sans tout refaire</li><li>Et la carte, vous pourrez la modifier vous-même en deux minutes</li></ul><br><em>Conseil : comparez toujours avec ce qu'il fait déjà — Google, Instagram, un PDF de carte. Ça le rassure.</em>"}
{"code": "pres-restauration-closing", "type": "presentation", "sector": "restauration", "stage": "closing", "title": "Restaurant ou traiteur — closing", "content": "<p>Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions. On est sur la dernière ligne pour votre site.</p><ul><li>La maquette vous a plu, il ne reste que les photos de plats à récupérer</li><li>Le devis inclut la mise en ligne et la réservation</li><li>Voulez-vous que la mise en ligne se fasse avant ou après votre prochaine carte ?</li></ul><br><em>Conseil : une date de mise en ligne précise vaut mieux qu'un « dès que possible ».</em>"}
{"code": "pres-services-b2b-premier-appel", "type": "presentation", "sector": "services-b2b", "stage": "premier-appel", "title": "Entreprise de services B2B — premier contact", "content": "<p>Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions. Nous équipons des entreprises de services avec un site qui génère des rendez-vous, et des outils pour suivre les devis.</p><p>La plupart de celles qu'on accompagne perdent des opportunités sans savoir où.</p><ul><li>Un site clair, orienté prise de rendez-vous</li><li>Des relances automatiques sur les devis non signés</li><li>Un seul interlocuteur, un devis écrit sans engagement</li></ul><br><em>Conseil : en B2B, le premier appel sert surtout à obtenir un rendez-vous, pas à vendre le projet.</em>"}
{"code": "pres-services-b2b-relance", "type": "presentation", "sector": "services-b2b", "stage": "relance", "title": "Services B2B — relance", "content": "<p>Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions. Je vous avais envoyé la proposition pour votre site.</p><ul><li>Avez-vous pu la parcourir, ou je vous en résume les deux lignes essentielles ?</li><li>Le budget est celui du devis, et on peut démarrer par une première étape seule</li><li>Ça vous dit qu'on en parle dix minutes, avec la personne qui valide ?</li></ul><br><em>Conseil : en B2B, demandez toujours qui décide. Un « je dois en parler » arrive très vite.</em>"}
{"code": "pres-services-b2b-closing", "type": "presentation", "sector": "services-b2b", "stage": "closing", "title": "Services B2B — closing", "content": "<p>Bonjour {contact}, {prenom_commercial} de Prime Vision Solutions. On arrive au moment de décider.</p><ul><li>Le devis reprend votre périmètre, le prix et le calendrier</li><li>La livraison se fait par étapes : vous validez chaque palier avant le suivant</li><li>Si tout vous convient, je vous envoie le devis à signer aujourd'hui</li></ul><br><em>Conseil : après la question finale, ne remplissez pas le silence. Comptez jusqu'à cinq.</em>"}
